<?php ?><!doctype html><html lang="sw"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ramani Majengo — AI Architectural Planner</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@500;600;700&display=swap" rel="stylesheet"><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/css/bootstrap.min.css" rel="stylesheet"><style>:root{--ink:#252923;--muted:#687066;--cream:#f5f1e9;--paper:#fffdf9;--green:#53664d;--line:#e6e0d6}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--cream);color:var(--ink);font-family:'DM Sans',sans-serif}h1,h2,h3,h4{font-family:'Playfair Display',serif}.navbar{background:#fffdf9;border-bottom:1px solid var(--line)}.brand-mark{width:40px;height:40px;border:1px solid var(--ink);display:grid;place-items:center;font-family:'Playfair Display'}.brand{font-weight:700;letter-spacing:.08em;font-size:.82rem}.btn-main{background:var(--green);color:#fff;border:0;border-radius:0;padding:13px 22px;font-weight:700}.hero{min-height:690px;position:relative;overflow:hidden;background:#30352f}.hero-slide{position:absolute;inset:0;background-size:cover;background-position:center;opacity:0;transform:scale(1.04);transition:opacity 1.2s ease,transform 8s ease}.hero-slide.active{opacity:1;transform:scale(1)}.hero:after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,rgba(20,24,19,.75),rgba(20,24,19,.3))}.hero-content{position:relative;z-index:2;color:#fff;padding:170px 0 90px;max-width:760px}.eyebrow,.section-label{font-size:.72rem;text-transform:uppercase;letter-spacing:.18em;font-weight:700}.hero h1{font-size:clamp(3rem,6vw,6.2rem);line-height:.98}.hero p{font-size:1.08rem;line-height:1.8;color:#eee}.section{padding:90px 0}.paper,.result-card{background:var(--paper);border:1px solid var(--line)}.planner-card{padding:38px;box-shadow:0 20px 60px rgba(47,42,32,.08)}.form-label{font-size:.76rem;font-weight:700;text-transform:uppercase;letter-spacing:.08em;color:#626a61}.form-control,.form-select{border-radius:0;border:1px solid #d9d4ca;padding:13px 14px}.form-control:focus,.form-select:focus{border-color:var(--green);box-shadow:0 0 0 .2rem rgba(83,102,77,.1)}textarea.form-control{min-height:190px}.note{font-size:.78rem;color:var(--muted)}.inspiration-row{display:flex;gap:18px;overflow:auto;scrollbar-width:none}.inspiration-row::-webkit-scrollbar{display:none}.inspire{min-width:235px;height:310px;position:relative;overflow:hidden}.inspire img{width:100%;height:100%;object-fit:cover;transition:transform .8s}.inspire:hover img{transform:scale(1.06)}.inspire span{position:absolute;left:18px;bottom:17px;color:#fff;font-weight:700}.process{background:#303a2d;color:#fff}.step{border-top:1px solid rgba(255,255,255,.2);padding:22px 0}.result{display:none}.result-head{background:#303a2d;color:#fff;padding:50px 0}.result-card{padding:28px;height:100%}.metric{font-size:2rem;font-family:'Playfair Display';font-weight:600}.floor-wrap{background:#f0ede6;padding:18px;overflow:auto}.floor{position:relative;background:#fff;border:2px solid #2d332d;min-width:650px;height:470px}.room{position:absolute;border:1px solid #51584f;background:#fbfaf6;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;padding:6px;font-size:12px}.room strong{font-size:13px}.room em{font-style:normal;color:#777;font-size:11px}.flow-line{padding:16px 0;border-bottom:1px solid var(--line);display:flex;gap:16px}.flow-num{width:34px;height:34px;background:var(--green);color:#fff;border-radius:50%;display:grid;place-items:center;flex:0 0 auto;font-weight:700}.exterior-stage{background:#171b17;min-height:460px;display:grid;place-items:center;overflow:hidden}.exterior-stage img{width:100%;height:auto;max-height:700px;object-fit:cover;transition:transform 1.2s ease}.exterior-stage:hover img{transform:scale(1.025)}.exterior-placeholder{padding:80px 25px;text-align:center;color:#b9c0b5}.loading-overlay{display:none;position:fixed;inset:0;background:rgba(30,34,29,.7);z-index:2000;align-items:center;justify-content:center}.loading-box{background:#fffdf9;padding:35px;max-width:430px;width:90%;text-align:center}.loader-bar{height:3px;background:#ddd;margin-top:22px;overflow:hidden}.loader-bar i{display:block;width:35%;height:100%;background:var(--green);animation:load 1.2s infinite ease-in-out}@keyframes load{0%{transform:translateX(-110%)}100%{transform:translateX(330%)}}footer{background:#20251f;color:#dce2d9;padding:45px 0}@media(max-width:767px){.hero{min-height:610px}.hero-content{padding-top:130px}.planner-card{padding:23px}.section{padding:65px 0}.floor{min-width:600px}}</style></head><body><nav class="navbar navbar-expand-lg sticky-top"><div class="container py-2"><a class="navbar-brand d-flex align-items-center gap-2" href="#top"><span class="brand-mark">RM</span><span class="brand">RAMANI MAJENGO</span></a><button class="navbar-toggler" data-bs-toggle="collapse" data-bs-target="#nav">☰</button><div id="nav" class="collapse navbar-collapse"><ul class="navbar-nav ms-auto gap-lg-3"><li class="nav-item"><a class="nav-link" href="#planner">Planner</a></li><li class="nav-item"><a class="nav-link" href="#inspiration">Inspiration</a></li><li class="nav-item"><a class="nav-link" href="#method">How it works</a></li><li class="nav-item"><a class="btn btn-main" href="#planner">Anza kupanga</a></li></ul></div></div></nav><main id="top"><section class="hero"><div class="hero-slide active" style="background-image:url('https://images.pexels.com/photos/7031607/pexels-photo-7031607.jpeg?auto=compress&cs=tinysrgb&w=1800')"></div><div class="hero-slide" style="background-image:url('https://images.pexels.com/photos/8134821/pexels-photo-8134821.jpeg?auto=compress&cs=tinysrgb&w=1800')"></div><div class="hero-slide" style="background-image:url('https://images.pexels.com/photos/9976121/pexels-photo-9976121.jpeg?auto=compress&cs=tinysrgb&w=1800')"></div><div class="hero-slide" style="background-image:url('https://images.pexels.com/photos/10610731/pexels-photo-10610731.jpeg?auto=compress&cs=tinysrgb&w=1800')"></div><div class="container hero-content"><div class="eyebrow">AI architectural space planning</div><h1>Eleza nyumba unayotaka. AI ipange.</h1><p>Andika maono yako kwa lugha yako ya kawaida. AI itachambua plot, spaces, circulation na dimensions kisha ionyeshe floor plan pamoja na exterior inayotokana na concept hiyo hiyo.</p><a class="btn btn-main mt-3" href="#planner">Anza concept yako</a></div></section><section class="section" id="planner"><div class="container"><div class="row g-5"><div class="col-lg-4"><div class="section-label text-success mb-3">01 — Your brief</div><h2 class="display-5">Mwambie mbunifu wako unachotaka.</h2><p class="text-secondary lh-lg mt-4">Huhitaji room list. Andika maelezo ya nyumba yako kwa lugha ya kawaida; AI itatoa spaces na vipimo vya awali yenyewe.</p><div class="p-4 mt-4 border-start border-3" style="border-color:var(--green)!important;background:#eee9df"><strong>Tip</strong><div class="note mt-2">Mfano: nyumba ya familia ya kisasa yenye privacy, bedrooms, living kubwa, kitchen, dining, veranda na parking.</div></div></div><div class="col-lg-8"><form id="plannerForm" class="paper planner-card"><div class="row g-3"><div class="col-md-6"><label class="form-label">Jina la project</label><input name="project" class="form-control" placeholder="My Family House"></div><div class="col-md-6"><label class="form-label">Jina la mteja (optional)</label><input name="client" class="form-control"></div><div class="col-md-6"><label class="form-label">Contact (optional)</label><input name="contact" class="form-control"></div><div class="col-md-6"><label class="form-label">Location (optional)</label><input name="location" class="form-control"></div><div class="col-md-6"><label class="form-label">Plot width (m) *</label><input name="plot_width" type="number" step="0.1" min="1" class="form-control" required></div><div class="col-md-6"><label class="form-label">Plot depth (m) *</label><input name="plot_depth" type="number" step="0.1" min="1" class="form-control" required></div><div class="col-md-6"><label class="form-label">Road side</label><select name="road_side" class="form-select"><option>North</option><option>South</option><option>East</option><option>West</option></select></div><div class="col-md-6"><label class="form-label">Style preference</label><select name="style" class="form-select"><option value="">AI iamue kulingana na brief</option><option>Modern Tropical</option><option>Contemporary</option><option>Luxury</option><option>Minimalist</option><option>Courtyard</option><option>African Tropical</option></select></div><div class="col-12"><label class="form-label">Maelezo ya mteja *</label><textarea name="brief" class="form-control" required placeholder="Eleza nyumba unayotaka. Usijali room list au vipimo."></textarea></div><div class="col-12 d-flex justify-content-between align-items-center gap-3 flex-wrap"><div class="note">Plot dimensions + brief ndiyo msingi wa concept.</div><button class="btn btn-main" type="submit"><span class="btn-text">Tengeneza architectural concept</span><span class="spinner-border spinner-border-sm d-none"></span></button></div></div></form></div></div></div></section><section class="section pt-0" id="inspiration"><div class="container"><div class="d-flex justify-content-between align-items-end mb-4"><div><div class="section-label text-success mb-2">02 — Inspiration</div><h2>Architecture yenye character.</h2></div><div class="note">Photography: Pexels</div></div><div class="inspiration-row"><div class="inspire"><img src="https://images.pexels.com/photos/36175906/pexels-photo-36175906.jpeg?auto=compress&cs=tinysrgb&w=900"><span>Modern Tropical</span></div><div class="inspire"><img src="https://images.pexels.com/photos/7587880/pexels-photo-7587880.jpeg?auto=compress&cs=tinysrgb&w=900"><span>Contemporary</span></div><div class="inspire"><img src="https://images.pexels.com/photos/10610731/pexels-photo-10610731.jpeg?auto=compress&cs=tinysrgb&w=900"><span>Luxury</span></div><div class="inspire"><img src="https://images.pexels.com/photos/32206033/pexels-photo-32206033.jpeg?auto=compress&cs=tinysrgb&w=900"><span>Minimalist</span></div><div class="inspire"><img src="https://images.pexels.com/photos/9976121/pexels-photo-9976121.jpeg?auto=compress&cs=tinysrgb&w=900"><span>Courtyard</span></div><div class="inspire"><img src="https://images.pexels.com/photos/8134821/pexels-photo-8134821.jpeg?auto=compress&cs=tinysrgb&w=900"><span>African Tropical</span></div></div></div></section><section class="section process" id="method"><div class="container"><div class="row g-5"><div class="col-lg-5"><div class="section-label text-light mb-3">03 — The method</div><h2>Floor plan na exterior vinazungumza lugha moja.</h2><p class="text-white-50 lh-lg">Kwanza AI inatengeneza spatial concept. Kisha exterior image generator inatumia footprint, dimensions, spaces, road side na style ya concept hiyo hiyo.</p></div><div class="col-lg-7"><div class="step"><small>01</small><h4>Brief</h4><div class="text-white-50">AI inasoma mahitaji yako.</div></div><div class="step"><small>02</small><h4>Floor plan</h4><div class="text-white-50">Spaces, dimensions na flow vinaandaliwa.</div></div><div class="step"><small>03</small><h4>Exterior generation</h4><div class="text-white-50">AI inatengeneza realistic exterior kulingana na plan.</div></div><div class="step"><small>04</small><h4>Presentation board</h4><div class="text-white-50">Plan, dimensions, flow na exterior vinaonekana pamoja.</div></div></div></div></div></section><section id="results" class="result"><div class="result-head"><div class="container"><div class="section-label text-white-50 mb-3">Architectural concept</div><h2 id="rTitle" class="display-4">Concept</h2><p id="rSummary" class="lead text-white-50"></p></div></div><div class="section"><div class="container"><div id="clarify" class="alert alert-warning d-none"></div><div class="row g-4 mb-4"><div class="col-md-4"><div class="result-card"><div class="section-label">House width</div><div id="houseW" class="metric">—</div><div class="note">metres</div></div></div><div class="col-md-4"><div class="result-card"><div class="section-label">House depth</div><div id="houseD" class="metric">—</div><div class="note">metres</div></div></div><div class="col-md-4"><div class="result-card"><div class="section-label">Spaces extracted</div><div id="roomCount" class="metric">—</div><div class="note">from your brief</div></div></div></div><div class="row g-4"><div class="col-lg-8"><div class="result-card"><h3>Floor plan concept</h3><div class="floor-wrap mt-3"><div id="floor" class="floor"></div></div></div></div><div class="col-lg-4"><div class="result-card"><h3>Dimensions</h3><div id="dimensions" class="mt-3"></div></div></div><div class="col-lg-6"><div class="result-card"><h3>Room flow</h3><div id="flow" class="mt-3"></div></div></div><div class="col-lg-6"><div class="result-card"><h3>Exterior direction</h3><p id="outside" class="text-secondary lh-lg mt-3"></p></div></div><div class="col-12"><div class="result-card"><div class="d-flex justify-content-between align-items-center flex-wrap gap-2"><div><div class="section-label text-success">AI generated visual</div><h2 class="mb-1">Outside view — same house concept</h2><p class="text-secondary mb-0">Picha hii inatengenezwa kutoka kwenye dimensions na spaces za floor plan hii.</p></div><span id="imageStatus" class="badge text-bg-light">Inasubiri</span></div><div id="exteriorStage" class="exterior-stage mt-4"><div class="exterior-placeholder"><h3>Generating exterior…</h3><p class="mb-0">AI inalinganisha footprint, rooms, entrance na style kabla ya kutengeneza view.</p></div></div></div></div><div class="col-12"><div class="result-card"><h3>Architectural note</h3><p class="text-secondary mb-0">Hii ni preliminary concept. Setbacks, structure, drainage, soil conditions, regulations na construction drawings vinapaswa kuthibitishwa na architect/engineer mwenye sifa.</p></div></div></div></div></div></section></main><footer><div class="container"><div class="brand text-white">RAMANI MAJENGO</div><div class="mt-2 text-secondary">AI-assisted architectural concept planning.</div></div></footer><div class="loading-overlay" id="loading"><div class="loading-box"><div class="section-label text-success">Ramani Majengo</div><h3 class="mt-2">Tunapanga concept yako…</h3><p id="loadingText" class="text-secondary">Inasoma maelezo yako.</p><div class="loader-bar"><i></i></div></div></div><script src="https://code.jquery.com/jquery-3.7.1.min.js"></script><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/js/bootstrap.bundle.min.js"></script><script>$(function(){let slide=0,slides=$('.hero-slide');setInterval(function(){slides.eq(slide).removeClass('active');slide=(slide+1)%slides.length;slides.eq(slide).addClass('active')},6500);const msgs=['Inasoma maelezo yako.','Inatambua spaces na functions.','Inaangalia plot na proportions.','Inapanga circulation.','Inaandaa floor plan.'];function esc(v){return $('<div>').text(v==null?'':v).html()}function renderPlan(p){$('#rTitle').text(p.title||'Architectural Concept');$('#rSummary').text(p.summary||'');$('#houseW').text(Number(p.house_width||0).toFixed(2));$('#houseD').text(Number(p.house_depth||0).toFixed(2));let rooms=Array.isArray(p.rooms)?p.rooms:[];$('#roomCount').text(rooms.length);$('#dimensions').html(rooms.map(r=>`<div class="d-flex justify-content-between border-bottom py-2 gap-2"><span>${esc(r.name)}</span><strong>${Number(r.width).toFixed(2)} × ${Number(r.depth).toFixed(2)} m</strong></div>`).join(''));$('#flow').html(rooms.map((r,i)=>`<div class="flow-line"><div class="flow-num">${i+1}</div><div><strong>${esc(r.name)}</strong><div class="note">${Number(r.width).toFixed(2)} × ${Number(r.depth).toFixed(2)} m</div></div></div>`).join(''));$('#outside').text(p.outside_preview||'Exterior concept itaendana na floor plan, entrance, daylight, veranda/terrace, roofline na materials.');let W=Math.max(8,Number(p.house_width)||12),D=Math.max(8,Number(p.house_depth)||16),x=0,y=0,rowH=0,html='';rooms.forEach(r=>{let rw=Math.max(1,Number(r.width)||3),rd=Math.max(1,Number(r.depth)||3),px=Math.min(260,Math.max(75,rw/W*520)),py=Math.min(190,Math.max(65,rd/D*390));if(x+px>610){x=0;y+=rowH+2;rowH=0}if(y+py>430){x=0;y=0}html+=`<div class="room" style="left:${x}px;top:${y}px;width:${px}px;height:${py}px"><strong>${esc(r.name)}</strong><em>${rw.toFixed(2)} × ${rd.toFixed(2)} m</em></div>`;x+=px+2;rowH=Math.max(rowH,py)});$('#floor').html(html);$('#results').fadeIn(450);$('html,body').animate({scrollTop:$('#results').offset().top-65},700);generateExterior(p)}function generateExterior(p){$('#imageStatus').attr('class','badge text-bg-warning').text('Inatengeneza…');$('#exteriorStage').html('<div class="exterior-placeholder"><h3>AI inatengeneza outside view…</h3><p class="mb-0">Inatumia vipimo vya floor plan hii, si template ya nyumba nyingine.</p></div>');let data={house_width:p.house_width,house_depth:p.house_depth,plot_width:$('[name=plot_width]').val(),plot_depth:$('[name=plot_depth]').val(),road_side:$('[name=road_side]').val(),style:$('[name=style]').val(),rooms:p.rooms,outside_preview:p.outside_preview||'',brief:$('[name=brief]').val()};$.ajax({url:'api/exterior.php',method:'POST',contentType:'application/json',data:JSON.stringify(data),dataType:'json',timeout:150000}).done(function(r){if(r.ok&&r.image_url){$('#imageStatus').attr('class','badge text-bg-success').text('Generated');$('#exteriorStage').html(`<img src="${esc(r.image_url)}" alt="AI generated exterior concept based on floor plan">`)}else{$('#imageStatus').attr('class','badge text-bg-danger').text('Failed');$('#exteriorStage').html(`<div class="exterior-placeholder"><h3>Outside view haikutengenezwa</h3><p>${esc(r.message||'Jaribu tena.')}</p></div>`)}}).fail(function(xhr){let m='Exterior generation imeshindikana.';try{let j=JSON.parse(xhr.responseText);if(j.message)m=j.message}catch(e){}$('#imageStatus').attr('class','badge text-bg-danger').text('Failed');$('#exteriorStage').html(`<div class="exterior-placeholder"><h3>Outside view haikutengenezwa</h3><p>${esc(m)}</p></div>`)})}$('#plannerForm').on('submit',function(e){e.preventDefault();let data={};$(this).serializeArray().forEach(x=>data[x.name]=x.value);$('#loading').css('display','flex');let i=0,timer=setInterval(()=>$('#loadingText').text(msgs[++i%msgs.length]),1100);$('.btn-text').addClass('d-none');$('.spinner-border').removeClass('d-none');$('#clarify').addClass('d-none').empty();$.ajax({url:'api/generate.php',method:'POST',contentType:'application/json',data:JSON.stringify(data),dataType:'json',timeout:90000}).done(function(res){if(!res.ok){alert(res.message||'AI service haikupatikana.');return}let p=res.plan||{};if(p.needs_clarification){$('#clarify').removeClass('d-none').html('<strong>AI inahitaji clarification:</strong><ul class="mb-0 mt-2">'+(p.questions||[]).map(q=>'<li>'+esc(q)+'</li>').join('')+'</ul>');$('#results').fadeIn(350);$('html,body').animate({scrollTop:$('#results').offset().top-65},600);return}renderPlan(p)}).fail(function(xhr){let m='Imeshindikana kuwasiliana na AI service.';try{let j=JSON.parse(xhr.responseText);if(j.message)m=j.message}catch(e){}alert(m)}).always(function(){clearInterval(timer);$('#loading').hide();$('.btn-text').removeClass('d-none');$('.spinner-border').addClass('d-none')})});$('a[href^="#"]').on('click',function(e){let t=$(this).attr('href');if(t&&t!=='#'&&$(t).length){e.preventDefault();$('html,body').animate({scrollTop:$(t).offset().top-65},500)}})});</script></body></html>